# qx2_unique :: [1, 2, 2, 3, 3, 3]
def qx2_unique(xs):
    out = []
    seen = set()
    for x in xs:
        if x not in seen:
            out.append(x)
            seen.add(x)
    return out

if __name__ == '__main__':
    print(qx2_unique([1, 2, 2, 3, 3, 3]))

